import{_ as t,o as i,c as a,ai as n}from"./chunks/framework.DnX3IzGy.js";const h=JSON.parse('{"title":"OAuth2 Integration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"integrator-guide/oauth2/index.md","filePath":"integrator-guide/oauth2/index.md"}'),r={name:"integrator-guide/oauth2/index.md"};function o(s,e,l,c,d,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="oauth2-integration-guide" tabindex="-1">OAuth2 Integration Guide <a class="header-anchor" href="#oauth2-integration-guide" aria-label="Permalink to &quot;OAuth2 Integration Guide&quot;">​</a></h1><p>Citizen iD has been designed from the ground up to be a secure and flexible identity provider, built on the widely adopted <a href="https://datatracker.ietf.org/doc/html/rfc6749" title="RFC6749: OAuth 2.0 Authorization Framework" target="_blank" rel="noreferrer">OAuth2</a> and OpenID Connect (OIDC) standards. This guide provides an overview of how to set up and use Citizen iD as an OAuth2 provider.</p><h2 id="becoming-an-integrator" tabindex="-1">Becoming an Integrator <a class="header-anchor" href="#becoming-an-integrator" aria-label="Permalink to &quot;Becoming an Integrator&quot;">​</a></h2><p>To integrate your application with Citizen iD, you first need to register as an integrator. This process involves granting your account an integrator role and access and agreeing to the terms of service for integrators.</p><p>To register, please follow the instructions in the <a href="/integrator-guide/registration.html">integrator registration guide</a>.</p><h2 id="managing-client-applications" tabindex="-1">Managing Client Applications <a class="header-anchor" href="#managing-client-applications" aria-label="Permalink to &quot;Managing Client Applications&quot;">​</a></h2><p>Once registered as an integrator, you can create and manage OAuth2 client applications through the <a href="https://citizenid.space/developer" title="Citizen iD Developer Dashboard" target="_blank" rel="noreferrer">Citizen iD developer dashboard</a>.</p><p>Before creating a client application, you will be required to create a group that represents your organisation or project. This group will be associated with client applications you create and helps us manage and monitor usage. You can create multiple groups if needed, for example, to separate unrelated projects.</p><p>After creating a group, you can proceed to create a client application. When creating an application, you will need to decide on the type of application you are building, as this will determine the OAuth2 client type you should use:</p><ul><li><strong>Confidential clients</strong><br>These are applications that <strong>can securely store</strong> a client secret, such as server-side web applications.</li><li><strong>Public clients</strong><br>These are applications that <strong>cannot securely store</strong> and by extension use a client secret, such as single-page applications (SPAs) or mobile apps.</li></ul><p>Once you fill out the required information and create the application, you will be provided with a client ID and, if applicable, a client secret. Application secret can be reset at any time from the developer dashboard.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Make sure to store these credentials securely, as they authenticate your application with Citizen iD and authorise it to access and change relevant data.</p></div><h3 id="citizen-id-environments" tabindex="-1">Citizen iD Environments <a class="header-anchor" href="#citizen-id-environments" aria-label="Permalink to &quot;Citizen iD Environments&quot;">​</a></h3><p>The Citizen iD platform has two separate environments for development and production:</p><ul><li><strong>Staging environment</strong> <a href="https://citizenid.dev" title="Citizen iD Staging Environment" target="_blank" rel="noreferrer"><code>https://citizenid.dev</code></a><br>Here you can safely develop and test your integration without affecting real user data.</li><li><strong>Production environment</strong> <a href="https://citizenid.space" title="Citizen iD Production Environment" target="_blank" rel="noreferrer"><code>https://citizenid.space</code></a><br>This is the live environment where real user data is stored and accessed.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Once you have thoroughly tested your integration in the staging environment and are ready to go live, you can request approval and access to the production environment. Citizen iD staff will review your application and integration to ensure it meets our standards and guidelines before granting access.</p></div><hr><p><em>Last updated: March 2026</em></p>',18)]))}const g=t(r,[["render",o]]);export{h as __pageData,g as default};
